// Generates server/migration_v1_to_v2.sql = a warning header + drops of every v1 object + the whole of schema.sql (v2).
// Run: node build_migration.mjs   (the tests run it first, so the migration can never drift from the schema)
import fs from 'node:fs';
const schema = fs.readFileSync(new URL('./schema.sql', import.meta.url), 'utf8');
const header = `-- =====================================================================================================================
-- THE WORTHY ONE - MIGRATION v1 -> v2 (generated by build_migration.mjs; do not edit by hand, edit schema.sql and regenerate)
--
-- !! DESTRUCTIVE ON THE FIRST RUN !!  If the old v1 tables are present (detected by players.display_name) this DELETES them and everything
-- in them: players, runs, run_levels, records, flags, google_identities. v1 held only guest accounts and test data, no real scores.
-- Do NOT run it on a project that holds data you want to keep. It does not touch Supabase Auth users.
-- Once v2 exists the drop step does nothing, so running the file again is harmless and never deletes v2 accounts.
-- Keep "Allow anonymous sign-ins" ON in Authentication > Sign In / Providers (the app uses an anonymous session per install).
-- =====================================================================================================================

do $migrate$
begin
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'players' and column_name = 'display_name') then
    drop table if exists public.flags, public.records, public.run_levels, public.runs, public.google_identities, public.players cascade;
  end if;
end
$migrate$;
drop function if exists public.normalize_name(text), public.name_error(text), public._suffixed(text), public.register_player(text),
  public.set_display_name(text), public.link_google_identity(uuid, text), public.player_for_google(text), public.expire_stale_runs() cascade;

`;
fs.writeFileSync(new URL('./migration_v1_to_v2.sql', import.meta.url), header + schema);
console.log('wrote migration_v1_to_v2.sql');
